import requests
from bs4 import BeautifulSoup
from typing import Dict, Any, Optional
from omniagents.core import function_tool

@function_tool
def web_fetch(url: str, extract_text: bool) -> Dict[str, Any]:
    """
    Fetches content from a given URL and optionally extracts text content.
    
    Args:
        url: The URL to fetch content from.
        extract_text: Whether to extract and return text content (true) or return raw HTML (false).
    
    Returns:
        Dictionary with status, content, and metadata.
    
    Usage:
        This function requires all parameters to be explicitly provided.
        
    Example:
        web_fetch(
            url="https://example.com",
            extract_text=true
        )
    """
    try:
        # Make the request to the URL
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
        }
        
        response = requests.get(url, headers=headers, timeout=10)
        
        if response.status_code != 200:
            return {
                "status": "error",
                "error": f"Request failed with status code {response.status_code}: {response.text}"
            }
        
        # Get the content type from headers
        content_type = response.headers.get('Content-Type', '')
        
        # Check if response is HTML
        is_html = 'text/html' in content_type.lower()
        
        result = {
            "status": "success",
            "url": url,
            "content_type": content_type,
            "size": len(response.content),
            "headers": dict(response.headers)
        }
        
        # Process HTML content if requested and content is HTML
        if extract_text and is_html:
            soup = BeautifulSoup(response.text, 'html.parser')
            
            # Extract title
            title = soup.title.string if soup.title else ''
            result["title"] = title
            
            # Remove script and style elements
            for script in soup(["script", "style"]):
                script.extract()
            
            # Get text content
            text = soup.get_text(separator='\n', strip=True)
            
            # Clean up text: remove excessive newlines
            lines = [line.strip() for line in text.split('\n')]
            text = '\n'.join(line for line in lines if line)
            
            result["text_content"] = text
            
            # Extract metadata
            meta_tags = {}
            for meta in soup.find_all('meta'):
                name = meta.get('name') or meta.get('property')
                content = meta.get('content')
                if name and content:
                    meta_tags[name] = content
            
            result["meta_tags"] = meta_tags
            
            # Extract links
            links = []
            for link in soup.find_all('a', href=True):
                href = link['href']
                text = link.get_text(strip=True)
                if href and not href.startswith('#') and not href.startswith('javascript:'):
                    links.append({
                        "href": href,
                        "text": text if text else None
                    })
            
            result["links"] = links[:100]  # Limit to 100 links
        else:
            # Return raw content
            result["raw_content"] = response.text
        
        return result
        
    except requests.RequestException as e:
        return {
            "status": "error",
            "error": f"Network error occurred: {str(e)}"
        }
    except Exception as e:
        return {
            "status": "error",
            "error": f"Error during web fetch: {str(e)}"
        }



# --- From tools/shared/bash_tool.py ---
import subprocess
import os
from typing import Dict, Any, Optional
from omniagents.core import function_tool

@function_tool
def execute_bash(command: str, timeout: Optional[int]) -> Dict[str, Any]:
    """
    Executes a shell command in the user's environment and returns the output.
    
    Args:
        command: The shell command to execute
        timeout: Maximum execution time in seconds
        
    Returns:
        Dictionary containing:
        {
            "stdout": Command standard output (if successful)
            "stderr": Command standard error (if any)
            "returncode": Command exit code (0 indicates success)
            "error": Error message (if command execution failed)
        }
        
    Usage:
        Use this tool to execute shell commands for file operations, system
        queries, or any other CLI operations within the operating system.
        
    Safety Notes:
        - This tool executes commands directly in the system shell
        - Be careful with commands that can modify system state
        - Avoid running untrusted code or potentially harmful commands
        - If timeout is not provided, a default value of 30 seconds will be used
        
    Example:
        # List files in the current directory
        execute_bash("ls -la", timeout=30)
        
        # Find a file
        execute_bash("find . -name '*.py' -type f", timeout=60)
    """
    # Default timeout value if not provided
    if timeout is None:
        timeout = 30
        
    result = {
        "stdout": "",
        "stderr": "",
        "returncode": None
    }
    
    try:
        process = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout
        )
        
        result["stdout"] = process.stdout
        result["stderr"] = process.stderr
        result["returncode"] = process.returncode
        
        return result
    except subprocess.TimeoutExpired:
        return {"error": f"Command timed out after {timeout} seconds"}
    except Exception as e:
        return {"error": f"Error executing command: {str(e)}"}



# --- From tools/shared/weather.py ---
import requests
from typing import Dict, Any
from requests.exceptions import HTTPError
from omniagents.core import function_tool

@function_tool
def get_weather(latitude: float, longitude: float) -> Dict[str, Any]:
    """
    Returns the current weather conditions for a given latitude and longitude using the Open-Meteo API.
    
    Args:
        latitude: Latitude coordinate of the location (decimal degrees)
        longitude: Longitude coordinate of the location (decimal degrees)
        
    Returns:
        Dictionary containing weather data with the following structure:
        {
            "latitude": 40.71,
            "longitude": -74.01,
            "timezone": "America/Chicago",
            "current": {
                "time": "2023-08-11T12:00",
                "temperature_2m": 25.3,
                "is_day": 1,
                "precipitation": 0.0,
                "rain": 0.0,
                "showers": 0.0,
                "snowfall": 0.0
            },
            "current_units": {
                "temperature_2m": "°C",
                "precipitation": "mm",
                ...
            }
        }
        
    Usage:
        This function requires precise coordinates. First use the geocode function 
        to convert a city name to coordinates, then call this function.
        
    Example:
        geo_data = geocode("London")
        weather = get_weather(
            latitude=geo_data["results"][0]["latitude"],
            longitude=geo_data["results"][0]["longitude"]
        )
    """
    url = f"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,is_day,precipitation,rain,showers,snowfall&timezone=America%2FChicago"

    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except HTTPError as http_err:
        return {"error": f"HTTP error occurred: {http_err}"}
    except Exception as err:
        return {"error": f"Other error occurred: {err}"}


# --- From tools/shared/scholar_search.py ---
import os
import json
import requests
from typing import Dict, Any, Optional, Literal
from omniagents.core import function_tool

@function_tool
def scholar_search(query: str,
                  num_results: int,
                  sort_by: Literal["relevance", "date"],
                  publication_date: Optional[Literal["since_2023", "since_2020", "since_2017", "since_2014"]],
                  author: Optional[str]) -> Dict[str, Any]:
    """
    Searches Google Scholar for academic papers and citations.
    
    Args:
        query: Search query string.
        num_results: Number of results (max 20 per page).
        sort_by: "relevance" or "date".
        publication_date: Filter by: "since_2023", "since_2020", "since_2017", "since_2014".
        author: Filter by specific author.
    
    Returns:
        Dictionary with Scholar search results and metadata.
    """
    try:
        # Try to get the SerpAPI key from environment variables
        api_key = os.environ.get("SERPAPI_API_KEY")
        
        if not api_key:
            return {
                "status": "error",
                "error": "SERPAPI_API_KEY not found in environment variables. Please set this variable to use Google Scholar search."
            }
        
        # Base URL for SerpAPI Google Scholar endpoint
        base_url = "https://serpapi.com/search"
        
        # Prepare parameters
        params = {
            "q": query,
            "api_key": api_key,
            "engine": "google_scholar",
            "num": min(num_results, 20),  # Google Scholar typically shows 10-20 results per page
            "hl": "en"                    # Language set to English
        }
        
        # Add author filter if provided
        if author:
            params["as_user"] = author
        
        # Add sorting preference
        if sort_by == "date":
            params["as_sdt"] = "0,5"  # Sort by date
        
        # Add publication date filter
        if publication_date:
            date_filters = {
                "since_2023": "2023",
                "since_2020": "2020",
                "since_2017": "2017",
                "since_2014": "2014"
            }
            if publication_date in date_filters:
                params["as_ylo"] = date_filters[publication_date]
        
        # Always include citations, patents, and profile results
        
        # Make the request to SerpAPI
        response = requests.get(base_url, params=params)
        
        if response.status_code != 200:
            return {
                "status": "error",
                "error": f"SerpAPI request failed with status code {response.status_code}: {response.text}"
            }
        
        # Parse the response
        search_results = response.json()
        
        # Extract and structure the results
        result = {
            "status": "success",
            "query": query,
            "organic_results": [],
            "citation_results": [],
            "profiles": [],
            "related_searches": []
        }
        
        # Add organic search results (articles and papers)
        if "organic_results" in search_results:
            for item in search_results["organic_results"]:
                paper_info = {
                    "title": item.get("title", ""),
                    "link": item.get("link", ""),
                    "snippet": item.get("snippet", ""),
                    "publication_info": item.get("publication_info", {})
                }
                
                # Extract authors
                if "authors" in item:
                    paper_info["authors"] = item["authors"]
                
                # Extract citations
                if "inline_links" in item and "cited_by" in item["inline_links"]:
                    paper_info["cited_by"] = {
                        "total": item["inline_links"]["cited_by"].get("total", 0),
                        "link": item["inline_links"]["cited_by"].get("link", "")
                    }
                
                # Extract related versions if available
                if "versions" in item.get("inline_links", {}):
                    paper_info["versions"] = {
                        "total": item["inline_links"]["versions"].get("total", 0),
                        "link": item["inline_links"]["versions"].get("link", "")
                    }
                
                # Extract PDF link if available
                if "resources" in item:
                    for resource in item["resources"]:
                        if resource.get("title") == "PDF":
                            paper_info["pdf_link"] = resource.get("link", "")
                            break
                
                result["organic_results"].append(paper_info)
        
        # Add citation results if present
        if "citations" in search_results:
            result["citation_results"] = search_results["citations"]
        
        # Add profiles if present
        if "profiles" in search_results:
            result["profiles"] = search_results["profiles"]
        
        # Add related searches if available
        if "related_searches" in search_results:
            result["related_searches"] = search_results["related_searches"]
        
        # Add pagination information
        if "pagination" in search_results:
            result["pagination"] = search_results["pagination"]
        
        # Add search metadata
        result["search_metadata"] = {
            "id": search_results.get("search_metadata", {}).get("id", ""),
            "status": search_results.get("search_metadata", {}).get("status", ""),
            "total_time_taken": search_results.get("search_metadata", {}).get("total_time_taken", 0),
            "engine": "Google Scholar"
        }
        
        return result
        
    except requests.RequestException as e:
        return {
            "status": "error",
            "error": f"Network error occurred: {str(e)}"
        }
    except json.JSONDecodeError:
        return {
            "status": "error",
            "error": "Failed to parse the search results."
        }
    except Exception as e:
        return {
            "status": "error",
            "error": f"Error during Google Scholar search: {str(e)}"
        }


# --- From tools/shared/file_tools.py ---
import os
import glob
import re
from typing import Dict, Any, List, Optional
from omniagents.core import function_tool

@function_tool
def glob_files(pattern: str, path: Optional[str]) -> Dict[str, Any]:
    """
    Finds files based on pattern matching using glob patterns.
    
    Args:
        pattern: The glob pattern to match files (e.g., "*.py", "**/*.json")
        path: The directory to search in
        
    Returns:
        Dictionary containing:
        {
            "matches": List of file paths matching the pattern
            "count": Number of matches found
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to find files matching specific patterns.
        Common patterns:
        - "*.py": All Python files in the current directory
        - "**/*.json": All JSON files in the current directory and subdirectories
        - "src/*.js": All JavaScript files in the src directory
        - If path is not provided, current directory "./" will be used
        
    Examples:
        # Find all Python files in the current directory
        glob_files("*.py", path="./")
        
        # Find all JSON files recursively
        glob_files("**/*.json", path="./")
        
        # Find all log files in a specific directory
        glob_files("*.log", path="/var/log")
    """
    try:
        # Default to current directory if path is not provided
        if path is None:
            path = "."
            
        # Construct the full glob pattern
        full_pattern = os.path.join(path, pattern)
        
        # Find matching files
        matches = glob.glob(full_pattern, recursive=True)
        
        # Sort matches by modification time (newest first)
        matches.sort(key=lambda x: os.path.getmtime(x) if os.path.exists(x) else 0, reverse=True)
        
        return {
            "matches": matches,
            "count": len(matches)
        }
    except Exception as e:
        return {"error": f"Error finding files: {str(e)}"}

@function_tool
def grep_files(pattern: str, path: Optional[str], include: Optional[str]) -> Dict[str, Any]:
    """
    Searches for patterns in file contents using regular expressions.
    
    Args:
        pattern: The regular expression pattern to search for
        path: The directory to search in
        include: Optional file pattern to filter which files to search (e.g., "*.py")
        
    Returns:
        Dictionary containing:
        {
            "matches": List of dictionaries containing file paths and matching lines
            "count": Total number of matches found
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to search file contents for specific patterns.
        - If path is not provided, current directory "./" will be used
        - If include is not provided, all files will be searched
        
    Examples:
        # Find all occurrences of "TODO" in Python files
        grep_files("TODO", path="./", include="*.py")
        
        # Search for function definitions in the src directory
        grep_files("def\\s+\\w+\\(", path="src", include="*.py")
        
        # Find all imports in Python files
        grep_files("^import\\s+\\w+", path="./", include="*.py")
    """
    try:
        # Default to current directory if path is not provided
        if path is None:
            path = "."
            
        results = []
        total_matches = 0
        
        # Compile the regex pattern
        regex = re.compile(pattern)
        
        # Get files to search based on include pattern
        files_to_search = []
        if include is not None:
            glob_result = glob_files(include, path)
            if "error" in glob_result:
                return glob_result
            files_to_search = glob_result["matches"]
        else:
            # If no include pattern, use recursive glob to find all files
            glob_result = glob_files("**", path)
            if "error" in glob_result:
                return glob_result
            files_to_search = [f for f in glob_result["matches"] if os.path.isfile(f)]
        
        # Sort files by modification time (newest first)
        files_to_search.sort(key=lambda x: os.path.getmtime(x) if os.path.exists(x) else 0, reverse=True)
        
        # Search through files
        for file_path in files_to_search:
            try:
                with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
                    file_matches = []
                    for i, line in enumerate(f, 1):
                        if regex.search(line):
                            file_matches.append({"line_number": i, "content": line.rstrip()})
                    
                    if file_matches:
                        results.append({
                            "file": file_path,
                            "matches": file_matches,
                            "match_count": len(file_matches)
                        })
                        total_matches += len(file_matches)
            except Exception as e:
                # Skip files that can't be read
                continue
        
        return {
            "matches": results,
            "count": total_matches
        }
    except Exception as e:
        return {"error": f"Error searching files: {str(e)}"}

@function_tool
def list_directory(path: str, recursive: Optional[bool]) -> Dict[str, Any]:
    """
    Lists files and directories in the specified path.
    
    Args:
        path: The directory path to list contents of
        recursive: Whether to list contents recursively
        
    Returns:
        Dictionary containing:
        {
            "files": List of file paths
            "directories": List of directory paths
            "count": Total number of entries
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to list directory contents.
        - If recursive is not provided, it defaults to False
        
    Examples:
        # List contents of the current directory
        list_directory(".", recursive=False)
        
        # List contents of a specific directory recursively
        list_directory("/path/to/directory", recursive=True)
    """
    try:
        # Default to non-recursive if not specified
        if recursive is None:
            recursive = False
            
        files = []
        directories = []
        
        if recursive:
            for root, dirs, filenames in os.walk(path):
                # Add directories
                for dir_name in dirs:
                    dir_path = os.path.join(root, dir_name)
                    directories.append(dir_path)
                
                # Add files
                for filename in filenames:
                    file_path = os.path.join(root, filename)
                    files.append(file_path)
        else:
            # List only the specified directory
            with os.scandir(path) as entries:
                for entry in entries:
                    if entry.is_file():
                        files.append(entry.path)
                    elif entry.is_dir():
                        directories.append(entry.path)
        
        # Sort by name
        files.sort()
        directories.sort()
        
        return {
            "files": files,
            "directories": directories,
            "count": len(files) + len(directories)
        }
    except Exception as e:
        return {"error": f"Error listing directory: {str(e)}"}

@function_tool
def read_file(file_path: str, start_line: Optional[int], num_lines: Optional[int]) -> Dict[str, Any]:
    """
    Reads the contents of a file.
    
    Args:
        file_path: Path to the file to read
        start_line: Line number to start reading from (0-indexed)
        num_lines: Maximum number of lines to read
        
    Returns:
        Dictionary containing:
        {
            "content": The file content as a string
            "lines": List of lines in the file
            "line_count": Total number of lines read
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to read the contents of files.
        - If start_line is not provided, it defaults to 0 (first line)
        - If num_lines is not provided, all remaining lines will be read
        
    Examples:
        # Read an entire file
        read_file("/path/to/file.txt", start_line=0, num_lines=null)
        
        # Read 10 lines starting from line 5
        read_file("/path/to/file.txt", start_line=5, num_lines=10)
    """
    try:
        # Default to start at beginning if not specified
        if start_line is None:
            start_line = 0
            
        with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
            # Read all lines
            all_lines = f.readlines()
            
            # Apply start_line and num_lines filters
            if start_line < 0:
                start_line = 0
            
            if start_line >= len(all_lines):
                start_line = len(all_lines) - 1 if all_lines else 0
            
            if num_lines is None:
                # Read all remaining lines
                selected_lines = all_lines[start_line:]
            else:
                # Read specified number of lines
                selected_lines = all_lines[start_line:start_line + num_lines]
            
            return {
                "content": "".join(selected_lines),
                "lines": selected_lines,
                "line_count": len(selected_lines)
            }
    except Exception as e:
        return {"error": f"Error reading file: {str(e)}"}

@function_tool
def edit_file(file_path: str, old_text: str, new_text: str) -> Dict[str, Any]:
    """
    Makes targeted edits to a specific file by replacing text.
    
    Args:
        file_path: Path to the file to edit
        old_text: The text to replace
        new_text: The replacement text
        
    Returns:
        Dictionary containing:
        {
            "success": Boolean indicating if the edit was successful
            "replacements": Number of replacements made
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to make specific text replacements in files.
        
    Examples:
        # Replace a function name in a Python file
        edit_file("/path/to/file.py", "def old_function()", "def new_function()")
        
        # Replace a configuration value
        edit_file("/path/to/config.json", '"debug": false', '"debug": true')
    """
    try:
        # Read the file content
        with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
        
        # Replace the text
        new_content, replacements = re.subn(re.escape(old_text), new_text, content)
        
        if replacements > 0:
            # Write the modified content back to the file
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(new_content)
            
            return {
                "success": True,
                "replacements": replacements
            }
        else:
            return {
                "success": False,
                "replacements": 0,
                "error": "No matches found for the specified text"
            }
    except Exception as e:
        return {"error": f"Error editing file: {str(e)}"}

@function_tool
def write_file(file_path: str, content: str, append: Optional[bool]) -> Dict[str, Any]:
    """
    Creates a new file or overwrites an existing file with the provided content.
    
    Args:
        file_path: Path to the file to write
        content: Content to write to the file
        append: Whether to append to the file instead of overwriting
        
    Returns:
        Dictionary containing:
        {
            "success": Boolean indicating if the write was successful
            "bytes_written": Number of bytes written
            "error": Error message (if any)
        }
        
    Usage:
        Use this tool to create or modify files.
        - If append is not provided, it defaults to False (overwrite mode)
        
    Examples:
        # Create a new Python file
        write_file("/path/to/new_file.py", "def hello_world():\n    print('Hello, world!')", append=False)
        
        # Append to a log file
        write_file("/path/to/log.txt", "New log entry\n", append=True)
    """
    try:
        # Default to overwrite if not specified
        if append is None:
            append = False
            
        # Ensure the directory exists
        os.makedirs(os.path.dirname(os.path.abspath(file_path)), exist_ok=True)
        
        # Write mode: 'a' for append, 'w' for overwrite
        mode = 'a' if append else 'w'
        
        with open(file_path, mode, encoding='utf-8') as f:
            bytes_written = f.write(content)
        
        return {
            "success": True,
            "bytes_written": bytes_written
        }
    except Exception as e:
        return {"error": f"Error writing file: {str(e)}"}


